#!/usr/bin/env node
// Trusted GitHub adapter. Candidate files and logs are data, never executable inputs.
import { createHash } from "node:crypto";
import { spawnSync } from "node:child_process";
import { pathToFileURL } from "node:url";
import { diagnostics, receipt, render, summaryAllowed } from "./automation-receipt.mjs";

export function ensure(condition, message) {
  if (!condition) throw new Error(message);
}
export const SHA = /^[a-f0-9]{40}$/;
const WORKFLOWS = new Set([".github/workflows/ci.yml", ".github/workflows/recovery-audit.yml", ".github/workflows/ai-edit.yml"]);
export function verifyRun(run, repository, id, attempt) {
  ensure(run.id === id && run.run_attempt === attempt, "Run identity mismatch");
  ensure(Number.isSafeInteger(id) && id > 0 && Number.isSafeInteger(attempt) && attempt > 0, "Invalid run identity");
  ensure(run.repository?.full_name === repository, "Repository mismatch");
  ensure(run.head_repository?.full_name === repository, "Fork runs are not publication targets");
  ensure(SHA.test(run.head_sha) && WORKFLOWS.has(run.path), "Unrecognized workflow or SHA");
  ensure(["push", "pull_request", "workflow_dispatch"].includes(run.event), "Unsupported event");
  ensure(run.status === "completed", "Run has not completed");
  return run;
}

export async function collectDiagnostics(fetchLogs) {
  for (let attempt = 0; attempt < 3; attempt++) {
    try { return diagnostics({ exit_code: 0, text: await fetchLogs() }); } catch {
      // A retrieval error is never passed off as test output.
    }
  }
  return diagnostics({ exit_code: 1, text: "" });
}

export async function reportOutcome(value, ports, detail = null, scope = "default") {
  const projection = render(value).body;
  ensure(/^(default|\d+)$/.test(String(scope)), "Invalid summary scope");
  await ports.persist(value, detail);
  const head = value.published_sha ?? value.head_sha ?? value.request_commit;
  if ((await ports.currentHead()) !== head) return { comment: "stale" };
  const prefix = `<!-- motion5-summary:${value.kind}:${scope}:`;
  const owned = (await ports.comments()).filter((comment) => comment.user?.id === 41898282 && comment.user?.type === "Bot" && comment.body?.startsWith(prefix));
  ensure(owned.length <= 1, "Multiple bot summaries require reconciliation");
  const previous = owned[0];
  const match = previous?.body.slice(prefix.length).match(/^([a-f0-9]{40}):(\d+):(\d+) -->/);
  ensure(!previous || match, "Malformed bot summary");
  const sameHead = match?.[1] === head;
  if (!summaryAllowed({current_head: head, incoming_head: head, incoming_run: value.run_id, incoming_attempt: value.run_attempt, ...(sameHead ? {previous_run: Number(match[2]), previous_attempt: Number(match[3])} : {})}).allowed) return {comment: "stale"};
  // Reporters are serialized by the workflow. GitHub comments have no conditional update API.
  if ((await ports.currentHead()) !== head) return {comment: "stale"};
  const body = `${prefix}${head}:${value.run_id}:${value.run_attempt} -->\n${projection}`;
  await ports.writeComment(previous?.id ?? null, body);
  return {comment: (await ports.currentHead()) === head ? "published" : "published_historical"};
}

export async function boundedBody(response, limit) {
  const chunks = []; let bytes = 0;
  for await (const chunk of response.body) {
    bytes += chunk.length;
    ensure(bytes <= limit, "GitHub response exceeds byte limit");
    chunks.push(chunk);
  }
  return Buffer.concat(chunks);
}

export class GitHub {
  constructor(repository, token) {
    ensure(/^[A-Za-z0-9_.-]+\/[A-Za-z0-9_.-]+$/.test(repository), "Invalid repository");
    ensure(typeof token === "string" && token.length > 0, "Missing credential");
    this.repository = repository; this.token = token;
  }
  async request(method, path, body) {
    ensure(path.startsWith("/") && !path.includes("..") && !path.includes("\\") && !path.includes("#"), "Unsafe API path");
    const response = await fetch(`https://api.github.com/repos/${this.repository}${path}`, {method, headers: {Authorization: `Bearer ${this.token}`, Accept: "application/vnd.github+json", "X-GitHub-Api-Version": "2022-11-28", "Content-Type": "application/json"}, body: body === undefined ? undefined : JSON.stringify(body), signal: AbortSignal.timeout(30000), redirect: "error"});
    if (!response.ok) { const error = new Error(`GitHub request failed (${response.status})`); error.status = response.status; throw error; }
    const bytes = await boundedBody(response, 6000000);
    return bytes.length ? JSON.parse(bytes.toString("utf8")) : null;
  }
  async list(path, key = null) {
    const all = [];
    for (let page = 1; page <= 10; page++) {
      const data = await this.request("GET", `${path}${path.includes("?") ? "&" : "?"}per_page=100&page=${page}`);
      const rows = key ? data[key] : data;
      ensure(Array.isArray(rows), "Invalid GitHub collection"); all.push(...rows);
      if (rows.length < 100) return all;
    }
    throw new Error("GitHub collection exceeds pagination limit");
  }
  async content(path, ref) {
    ensure(SHA.test(ref), "Content reads require immutable SHA");
    const value = await this.request("GET", `/contents/${path.split("/").map(encodeURIComponent).join("/")}?ref=${ref}`);
    ensure(value.type === "file" && value.encoding === "base64" && value.size <= 1500000, "Expected bounded regular file");
    const bytes = Buffer.from(value.content, "base64");
    ensure(bytes.length === value.size && blobSha(bytes) === value.sha, "Incomplete or corrupt contents response");
    return {...value, text: bytes.toString("utf8")};
  }
  async run(id, attempt) {
    ensure(Number.isSafeInteger(id) && id > 0 && Number.isSafeInteger(attempt) && attempt > 0, "Invalid run identity");
    return verifyRun(await this.request("GET", `/actions/runs/${id}/attempts/${attempt}`), this.repository, id, attempt);
  }
  async head(branch) {
    ensure(typeof branch === "string" && branch.length > 0 && !/[\x00-\x20\\~^:?*\[]/.test(branch), "Unsafe branch");
    const ref = await this.request("GET", `/git/ref/heads/${encodeURIComponent(branch)}`);
    ensure(SHA.test(ref.object?.sha), "Invalid ref response"); return ref.object.sha;
  }
  async persist(files) {
    const entries = Object.entries(files);
    ensure(entries.length > 0 && entries.length <= 60, "Invalid evidence file count");
    for (const [path, content] of entries) {
      ensure(/^receipts\/(?:ci|ai-edit)\/[1-9]\d*\/[1-9]\d*\/(?:(?:receipt|intent|diagnostics|manifest)\.json|log-\d{3}\.txt)$/.test(path), "Invalid evidence destination");
      ensure(typeof content === "string", "Evidence must be text");
    }
    ensure(entries.reduce((sum, [, text]) => sum + Buffer.byteLength(text), 0) <= 1800000, "Evidence exceeds limit");
    for (let attempt = 0; attempt < 3; attempt++) {
      const head = await this.head("ci-logs");
      const commit = await this.request("GET", `/git/commits/${head}`);
      const tree = await this.request("GET", `/git/trees/${commit.tree.sha}?recursive=1`);
      ensure(!tree.truncated, "Evidence tree is incomplete");
      const existing = new Map(tree.tree.map((entry) => [entry.path, entry]));
      const changed = [];
      for (const [path, content] of entries) {
        const old = existing.get(path);
        if (old) ensure(old.type === "blob" && old.sha === blobSha(Buffer.from(content)), "Refusing to overwrite historical evidence");
        else changed.push({path, mode: "100644", type: "blob", content});
      }
      if (changed.length === 0) return;
      const nextTree = await this.request("POST", "/git/trees", {base_tree: commit.tree.sha, tree: changed});
      const next = await this.request("POST", "/git/commits", {message: "ci(automation): retain exact-run evidence", tree: nextTree.sha, parents: [head]});
      try { await this.request("PATCH", "/git/refs/heads/ci-logs", {sha: next.sha, force: false}); return; } catch {
        // Retry only evidence publication after re-reading the immutable files.
      }
    }
    throw new Error("Evidence publication could not be confirmed");
  }
}
export function blobSha(bytes) {
  return createHash("sha1").update(`blob ${bytes.length}\0`).update(bytes).digest("hex");
}
export async function persistOutcome(api, value, detail = null) {
  render(value);
  const directory = value.evidence_path.slice(0, -"receipt.json".length);
  const files = {[value.evidence_path]: `${JSON.stringify(value)}\n`};
  if (detail) {
    const {chunks, ...metadata} = detail;
    const paths = chunks.map((text, index) => {const path = `${directory}log-${String(index).padStart(3, "0")}.txt`; files[path] = text; return path;});
    files[`${directory}diagnostics.json`] = `${JSON.stringify({...metadata, paths})}\n`;
  }
  await api.persist(files);
}
export async function reportToPull(api, run, value, detail = null) {
  await persistOutcome(api, value, detail);
  const pulls = await api.list(`/commits/${run.head_sha}/pulls`);
  const verified = pulls.filter((pr) => pr.state === "open" && pr.base?.repo?.full_name === api.repository && pr.head?.repo?.full_name === api.repository && pr.head?.ref === run.head_branch);
  if (verified.length !== 1) return {comment: "no_unique_pr", evidence: value.evidence_path};
  const number = verified[0].number;
  ensure(Number.isSafeInteger(number) && number > 0, "Invalid PR number");
  return reportOutcome(value, {
    persist: async () => {},
    currentHead: async () => {const pr = await api.request("GET", `/pulls/${number}`); ensure(pr.head?.repo?.full_name === api.repository && pr.head.ref === run.head_branch, "PR association changed"); return pr.state === "open" ? pr.head.sha : null;},
    comments: () => api.list(`/issues/${number}/comments`),
    writeComment: (id, body) => id ? api.request("PATCH", `/issues/comments/${id}`, {body}) : api.request("POST", `/issues/${number}/comments`, {body}),
  }, null, String(run.workflow_id));
}
export async function reportCompletedRun(api, run, trustedSha) {
  ensure(SHA.test(trustedSha), "A reviewed immutable runner SHA is required");
  let tested = null;
  if (run.path === ".github/workflows/ci.yml") {
    const [actual, trusted] = await Promise.all([api.content(run.path, run.head_sha), api.content(run.path, trustedSha)]);
    if (actual.sha === trusted.sha) tested = run.head_sha;
  }
  const value = receipt({kind: "ci", repository: api.repository, run_id: run.id, run_attempt: run.run_attempt, head_sha: run.head_sha, tested_sha: tested, ci: run.conclusion ?? "unavailable"});
  let exists = false;
  try {
    const saved = await api.content(value.evidence_path, await api.head("ci-logs"));
    ensure(saved.text === `${JSON.stringify(value)}\n`, "Existing receipt conflicts with run metadata"); exists = true;
  } catch (error) {if (error.status !== 404) throw error;}
  const detail = exists ? null : await collectDiagnostics(async () => {
    const result = spawnSync("gh", ["run", "view", String(run.id), "--repo", api.repository, "--attempt", String(run.run_attempt), "--log-failed"], {encoding: "utf8", timeout: 45000, maxBuffer: 8000000, env: {PATH: process.env.PATH, GH_TOKEN: api.token, HOME: process.env.RUNNER_TEMP ?? "/tmp"}});
    ensure(result.status === 0 && !result.error, "Log retrieval failed"); return result.stdout;
  });
  return reportToPull(api, run, value, detail);
}
if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  try {
    const api = new GitHub(process.env.GITHUB_REPOSITORY, process.env.GH_TOKEN);
    const run = await api.run(Number(process.env.REPORT_RUN_ID), Number(process.env.REPORT_RUN_ATTEMPT));
    ensure(run.path !== ".github/workflows/ai-edit.yml", "AI edits use the publication adapter");
    console.log(JSON.stringify(await reportCompletedRun(api, run, process.env.TRUSTED_SHA)));
  } catch (error) {console.error(error.message); process.exitCode = 1;}
}

#!/usr/bin/env node
// Publication owns the transition from a bounded candidate to a confirmed remote commit.
import { execFileSync, spawnSync } from "node:child_process";
import { mkdtemp, readFile, writeFile, readdir, lstat, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import path from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";
import { identity, receipt, render } from "./automation-receipt.mjs";
import { GitHub, SHA, ensure, boundedBody, persistOutcome, reportToPull } from "./automation-report.mjs";

function exactKeys(value, allowed) {
  ensure(value && typeof value === "object" && !Array.isArray(value), "Expected object");
  ensure(Object.keys(value).every((key) => allowed.includes(key)), "Unknown field");
}
function safePath(value) {
  ensure(typeof value === "string" && value.length > 0 && value.length <= 1024 && !/[\s\\\x00-\x1f\x7f]/u.test(value) && !value.startsWith("-") && value.split("/").every((part) => part && part !== "." && part !== ".."), "Unsafe candidate path");
  ensure(![".git", ".ai", ".github/workflows", "node_modules"].some((prefix) => value === prefix || value.startsWith(`${prefix}/`)), "Protected candidate path");
}
export function validateCandidate(candidate, expected) {
  exactKeys(candidate, ["version", "trusted_sha", "request_commit", "source_sha", "request_digest", "files"]);
  ensure(candidate.version === 1, "Unsupported candidate version");
  for (const key of ["trusted_sha", "request_commit", "source_sha", "request_digest"]) ensure(candidate[key] === expected[key], `Candidate ${key} mismatch`);
  ensure(Array.isArray(candidate.files) && candidate.files.length <= 50, "Invalid candidate files");
  ensure(Buffer.byteLength(JSON.stringify(candidate)) <= 1800000, "Candidate exceeds byte limit");
  const seen = new Set();
  for (const file of candidate.files) {
    exactKeys(file, ["path", "content"]); safePath(file.path);
    ensure(expected.paths.includes(file.path) && !seen.has(file.path), "Unexpected or duplicate candidate path"); seen.add(file.path);
    ensure(file.content === null || typeof file.content === "string", "Candidate content must be text or deletion");
    ensure(file.content === null || Buffer.byteLength(file.content) <= 1500000, "Candidate file exceeds byte limit");
  }
  ensure(!expected.dry_run || candidate.files.length === 0, "Dry run must not modify target files");
  return candidate.files;
}

export async function publishCandidate(facts, ports) {
  render(receipt(facts));
  const candidate = await ports.createCandidate();
  ensure(SHA.test(candidate), "Invalid candidate commit");
  const intent = receipt({...facts, phase: "publication", candidate_sha: candidate});
  const head = await ports.currentHead();
  if (head === candidate || await ports.contains(candidate, head)) {
    const result = receipt({...facts, phase: "publication", candidate_sha: candidate, published_sha: candidate});
    await ports.saveReceipt(result); return result;
  }
  ensure(head === facts.request_commit, "Branch advanced; publication refused");
  await ports.saveIntent(intent);
  try {await ports.advance(candidate);} catch {
    // A lost response is not evidence of a rejected push. Reconcile, never replay.
  }
  let confirmed = false;
  try {const remote = await ports.currentHead(); confirmed = remote === candidate || await ports.contains(candidate, remote);} catch {
    // Keep the candidate and its durable intent discoverable when remote state is unknown.
  }
  const result = confirmed ? receipt({...facts, phase: "publication", candidate_sha: candidate, published_sha: candidate}) : intent;
  await ports.saveReceipt(result); return result;
}

async function regular(file) {
  const stat = await lstat(file); ensure(stat.isFile() && !stat.isSymbolicLink(), "Expected regular file");
  ensure(stat.size <= 1800000, "File exceeds byte limit"); return readFile(file, "utf8");
}
export async function prepareCandidate(root, trustedSha, formatterRoot, output) {
  ensure(SHA.test(trustedSha), "A reviewed immutable runner SHA is required");
  const git = (...args) => execFileSync("git", args, {cwd: root, encoding: "utf8", maxBuffer: 2000000, timeout: 10000}).trim();
  for (const directory of [".ai", ".ai/edits"]) {const stat = await lstat(path.join(root, directory)); ensure(stat.isDirectory() && !stat.isSymbolicLink(), "Unsafe request directory");}
  const requests = (await readdir(path.join(root, ".ai/edits"))).filter((name) => name.endsWith(".json"));
  ensure(requests.length === 1 && /^[A-Za-z0-9][A-Za-z0-9._-]*\.json$/.test(requests[0]), "Expected one bounded request");
  const requestPath = `.ai/edits/${requests[0]}`;
  const parents = git("rev-list", "--parents", "-n", "1", "HEAD").split(" ");
  ensure(parents.length === 2 && parents.every((sha) => SHA.test(sha)), "Request commit needs one parent");
  const [requestCommit, source] = parents;
  ensure(git("diff", "--no-renames", "--name-only", source, requestCommit) === requestPath, "Request-only commit required");
  const request = JSON.parse(await regular(path.join(root, requestPath)));
  const scratch = await mkdtemp(path.join(tmpdir(), "motion5-prepare-"));
  try {
    const report = path.join(scratch, "report.md"), touched = path.join(scratch, "touched.txt"), format = path.join(scratch, "format.txt");
    const result = spawnSync(process.execPath, [fileURLToPath(new URL("./apply-ai-edit.mjs", import.meta.url)), requestPath, report, touched, format], {cwd: root, encoding: "utf8", timeout: 60000, maxBuffer: 2000000, env: {PATH: process.env.PATH, AI_EDIT_BASE_SHA: source}});
    ensure(result.status === 0 && !result.error, "Candidate application failed; disposable tree may be partially changed");
    const paths = (await readFile(touched, "utf8")).split("\n").filter(Boolean);
    const formattable = new Set((await readFile(format, "utf8")).split("\n").filter(Boolean));
    const prettier = await import(pathToFileURL(path.join(formatterRoot, "node_modules/prettier/index.mjs")).href);
    const options = JSON.parse(await readFile(new URL("../.prettierrc.json", import.meta.url), "utf8"));
    const files = [];
    for (const file of paths) {
      safePath(file);
      if (!formattable.has(file)) {files.push({path: file, content: null}); continue;}
      let content = await regular(path.join(root, file));
      const info = await prettier.getFileInfo(file, {resolveConfig: false});
      if (info.inferredParser) content = await prettier.format(content, {...options, parser: info.inferredParser});
      files.push({path: file, content});
    }
    const candidate = {version: 1, trusted_sha: trustedSha, request_commit: requestCommit, source_sha: source, request_digest: identity(request).digest, files};
    validateCandidate(candidate, {...candidate, paths: request.edits.map((edit) => edit.path), dry_run: request.dry_run === true});
    await writeFile(output, `${JSON.stringify(candidate)}\n`);
  } finally {await rm(scratch, {recursive: true, force: true});}
}

async function readCandidate(api, run) {
  const artifacts = await api.list(`/actions/runs/${run.id}/artifacts`, "artifacts");
  const matches = artifacts.filter((artifact) => artifact.name === `ai-edit-candidate-${run.id}-${run.run_attempt}` && !artifact.expired);
  ensure(matches.length === 1, "Candidate artifact is absent or ambiguous");
  const artifact = matches[0];
  ensure(Number.isSafeInteger(artifact.id) && artifact.size_in_bytes <= 2000000 && artifact.workflow_run?.head_sha === run.head_sha, "Artifact identity or size mismatch");
  const response = await fetch(`https://api.github.com/repos/${api.repository}/actions/artifacts/${artifact.id}/zip`, {headers: {Authorization: `Bearer ${api.token}`}, redirect: "manual", signal: AbortSignal.timeout(30000)});
  ensure(response.status === 302, "Artifact download unavailable");
  const location = new URL(response.headers.get("location"));
  ensure(location.protocol === "https:" && !location.username && !location.password, "Unsafe artifact redirect");
  // Never forward the GitHub credential to blob storage.
  const download = await fetch(location, {redirect: "error", signal: AbortSignal.timeout(30000)});
  ensure(download.ok, "Artifact download failed");
  const bytes = await boundedBody(download, 2000000);
  const scratch = await mkdtemp(path.join(tmpdir(), "motion5-artifact-"));
  try {
    const zip = path.join(scratch, "candidate.zip"); await writeFile(zip, bytes);
    const result = spawnSync("unzip", ["-p", zip, "candidate.json"], {encoding: "utf8", timeout: 10000, maxBuffer: 1800000, env: {PATH: process.env.PATH}});
    ensure(result.status === 0 && !result.error, "Candidate archive is unreadable or oversized");
    return JSON.parse(result.stdout);
  } finally {await rm(scratch, {recursive: true, force: true});}
}

async function snapshot(api, run, trustedSha) {
  ensure(SHA.test(trustedSha) && run.path === ".github/workflows/ai-edit.yml", "Untrusted publication workflow");
  ensure(run.event === "push" && run.head_branch !== "main" && run.head_branch !== "ci-logs", "Unsupported publication target");
  const [actual, trusted] = await Promise.all([api.content(run.path, run.head_sha), api.content(run.path, trustedSha)]);
  ensure(actual.sha === trusted.sha, "Candidate workflow differs from reviewed runner");
  const commit = await api.request("GET", `/git/commits/${run.head_sha}`);
  ensure(commit.parents.length === 1, "Request commit needs one parent");
  const source = commit.parents[0].sha;
  const sourceCommit = await api.request("GET", `/git/commits/${source}`);
  const [before, after] = await Promise.all([api.request("GET", `/git/trees/${sourceCommit.tree.sha}?recursive=1`), api.request("GET", `/git/trees/${commit.tree.sha}?recursive=1`)]);
  ensure(!before.truncated && !after.truncated, "Snapshot tree is incomplete");
  const original = new Map(before.tree.filter((entry) => entry.type !== "tree").map((entry) => [entry.path, entry]));
  const current = new Map(after.tree.filter((entry) => entry.type !== "tree").map((entry) => [entry.path, entry]));
  const changed = [...new Set([...original.keys(), ...current.keys()])].filter((file) => original.get(file)?.sha !== current.get(file)?.sha || original.get(file)?.mode !== current.get(file)?.mode);
  ensure(changed.length === 1 && /^\.ai\/edits\/[A-Za-z0-9][A-Za-z0-9._-]*\.json$/.test(changed[0]) && current.get(changed[0])?.mode === "100644", "Request-only regular-file snapshot required");
  const requestPath = changed[0];
  ensure([...current.keys()].filter((file) => /^\.ai\/edits\/.*\.json$/.test(file)).length === 1, "Multiple pending requests");
  const request = JSON.parse((await api.content(requestPath, run.head_sha)).text);
  ensure(request.version === 1 && request.expected_head === source && Array.isArray(request.edits) && request.edits.length > 0 && request.edits.length <= 50, "Invalid source request");
  const paths = [...new Set(request.edits.map((edit) => edit.path))];
  ensure(request.expected_blobs && Object.keys(request.expected_blobs).length === paths.length, "Invalid blob preconditions");
  for (const file of paths) {
    safePath(file);
    const entry = original.get(file);
    ensure(!entry || (entry.type === "blob" && ["100644", "100755"].includes(entry.mode)), "Non-regular source file");
    for (let parent = path.posix.dirname(file); parent !== "."; parent = path.posix.dirname(parent)) ensure(!original.has(parent), "Non-directory source ancestor");
    ensure(Object.hasOwn(request.expected_blobs, file) && request.expected_blobs[file] === (entry?.sha ?? null), "Source blob mismatch");
  }
  return {trusted_sha: trustedSha, request_commit: run.head_sha, source_sha: source, request_digest: identity(request).digest, request_path: requestPath, paths, dry_run: request.dry_run === true, request, commit, original};
}

export async function publishRun(api, writer, run, trustedSha) {
  const basic = {kind: "ai-edit", repository: api.repository, run_id: run.id, run_attempt: run.run_attempt, request_commit: run.head_sha};
  // Early failures do not require parsing a candidate-controlled request or artifact.
  if (run.conclusion !== "success") {
    const value = receipt({...basic, phase: "selection"});
    return reportToPull(api, run, value);
  }
  const state = await snapshot(api, run, trustedSha);
  const candidate = await readCandidate(api, run);
  const files = validateCandidate(candidate, state);
  const facts = {...basic, source_sha: state.source_sha, request_digest: state.request_digest, phase: "formatted"};
  const tree = files.map((file) => ({path: file.path, mode: state.original.get(file.path)?.mode ?? "100644", type: "blob", ...(file.content === null ? {sha: null} : {content: file.content})}));
  tree.push({path: state.request_path, mode: "100644", type: "blob", sha: null});
  const directory = `receipts/ai-edit/${run.id}/${run.run_attempt}/`;
  const result = await publishCandidate(facts, {
    createCandidate: async () => {
      const nextTree = await writer.request("POST", "/git/trees", {base_tree: state.commit.tree.sha, tree});
      const date = state.commit.committer.date;
      const actor = {name: "github-actions[bot]", email: "41898282+github-actions[bot]@users.noreply.github.com", date};
      const subject = state.dry_run ? "chore(ai-edit): dry run, nothing applied" : state.request.message;
      ensure(typeof subject === "string" && subject.length > 0 && !/[\x00-\x1f\x7f]/.test(subject) && !/\[(?:skip ci|ci skip|no ci|skip actions|actions skip)\]|skip-checks\s*:/i.test(subject), "Invalid commit subject");
      const commit = await writer.request("POST", "/git/commits", {message: `${subject}\n\nAI-Edit-Request: ${state.request_path}\nAI-Edit-Digest: ${state.request_digest}`, tree: nextTree.sha, parents: [run.head_sha], author: actor, committer: actor});
      return commit.sha;
    },
    currentHead: () => api.head(run.head_branch),
    contains: async (candidateSha, head) => {const comparison = await api.request("GET", `/compare/${candidateSha}...${head}`); return comparison.status === "ahead" || comparison.status === "identical";},
    saveIntent: (value) => api.persist({[`${directory}intent.json`]: `${JSON.stringify(value)}\n`}),
    // An uncertain publication retains intent, not an immutable false-negative terminal receipt.
    saveReceipt: (value) => value.publication === "confirmed" ? persistOutcome(api, value) : Promise.resolve(),
    advance: (sha) => writer.request("PATCH", `/git/refs/heads/${encodeURIComponent(run.head_branch)}`, {sha, force: false}),
  });
  if (result.publication !== "confirmed") throw new Error("Publication unconfirmed; inspect durable intent before retrying");
  return reportToPull(api, run, result);
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  try {
    if (process.argv[2] === "prepare") {
      await prepareCandidate(process.env.CANDIDATE_ROOT, process.env.TRUSTED_SHA, process.env.FORMATTER_ROOT, process.env.CANDIDATE_OUTPUT);
    } else if (process.argv[2] === "publish") {
      const api = new GitHub(process.env.GITHUB_REPOSITORY, process.env.GH_TOKEN);
      const writer = new GitHub(process.env.GITHUB_REPOSITORY, process.env.PUBLISH_TOKEN);
      const run = await api.run(Number(process.env.REPORT_RUN_ID), Number(process.env.REPORT_RUN_ATTEMPT));
      console.log(JSON.stringify(await publishRun(api, writer, run, process.env.TRUSTED_SHA)));
    } else throw new Error("Unknown operation");
  } catch (error) {console.error(error.message); process.exitCode = 1;}
}
